validator:
function validate(input) {
  const [{ Ads = [] }] = input;
  const seen = new Set(), actions = new Set(['Clicked', 'Viewed', 'Ignored']);
  for (const [ad, user, action] of Ads) {
    if (ad === null || user === null) return 'Every row needs an ad_id and a user_id.';
    if (!actions.has(action)) return "action must be 'Clicked', 'Viewed' or 'Ignored'.";
    const key = `${ad}/${user}`;
    if (seen.has(key)) return `User ${user} reacted to ad ${ad} twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  // Ignored is common so that some ads have no clicks or views at all.
  const actions = ['Clicked', 'Viewed', 'Ignored', 'Ignored', 'Clicked', 'Viewed', 'Ignored'];
  const adCount = small ? 1 + Math.floor(rand() * 4) : 250;
  const userCount = small ? 5 : 40;
  const pairs = [];
  for (let ad = 1; ad <= adCount; ad++) for (let user = 1; user <= userCount; user++) pairs.push([ad, user]);
  for (let i = pairs.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Ads = pairs.slice(0, count).map(([ad, user]) => [ad * 2 + 1, user, pick(actions)]);
  return [{ Ads }];
}
